effect.shader:
float gmHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float gmNoise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(gmHash(i),gmHash(i+vec2(1,0)),f.x),mix(gmHash(i+vec2(0,1)),gmHash(i+1.0),f.x),f.y);}
void main(){
vec2 uv=acScreenNorm; float c=cos(angle),s=sin(angle); vec2 q=mat2(c,-s,s,c)*(uv-0.5); float t=acTime*0.08+evolution;
float noise=gmNoise(vec2(q.y*4.0+t,q.x*2.0-t))*irregularity; float edge=(q.x+0.5)+noise*0.2;
float leak=1.0-smoothstep(width,width+max(softness,0.001),edge); leak+=0.35*(1.0-smoothstep(width*0.35,width*1.8,abs(edge-width*0.35+noise*0.08)));
leak=clamp(leak*intensity,0.0,3.0); vec3 leakColor=mix(innerColor.rgb,outerColor.rgb,clamp(edge/max(width,0.001),0.0,1.0))*leak;
vec4 src=texture2DCv(inputImg.texture,uv); vec3 result=1.0-(1.0-src.rgb)*(1.0-clamp(leakColor,0.0,1.0)); result+=max(leakColor-1.0,0.0)*0.35;
gl_FragColor=vec4(mix(src.rgb,result,mixAmount),src.a+clamp(leak,0.0,1.0)*mixAmount*(1.0-src.a));
}
